begin;
set local lock_timeout = '10s';
select set_config('seo_pp.run_id', :'run_id', true) run_id, set_config('seo_pp.rb_id', :'run_id' || '/rollback', true) rollback_id;
lock table public.pp_pools, public.pp_cities in share row exclusive mode;

do $$ begin
  if to_regclass('public.seo_repair_pp_change_log') is null or to_regclass('public.seo_repair_pp_backup_20261115') is null then
    raise exception 'ABORT: backup / change log tables do not exist';
  end if;
  if not exists (select 1 from public.seo_repair_pp_change_log where run_id = current_setting('seo_pp.run_id') and action = 'applied') then
    raise exception 'ABORT: run % applied nothing (or does not exist)', current_setting('seo_pp.run_id');
  end if;
end $$;

create temp table seo_pp_rb on commit drop as
with l as (
  select distinct on (tbl, row_id, col) rule_id, tbl, row_id, col, old_md5, new_md5
    from public.seo_repair_pp_change_log
   where run_id = current_setting('seo_pp.run_id') and action = 'applied'
   order by tbl, row_id, col, id desc),
cur as (
  select 'pp_pools'::text tbl, p.id row_id, v.col, md5(v.val) cur_md5
    from public.pp_pools p,
         lateral (values ('ai_best_for'::text, p.ai_best_for), ('ai_description', p.ai_description), ('ai_faqs', p.ai_faqs::text)) v(col, val)
   where p.id in (select row_id from l where tbl = 'pp_pools')
  union all
  select 'pp_cities', c.id, v.col, md5(v.val)
    from public.pp_cities c, lateral (values ('ai_intro'::text, c.ai_intro), ('ai_faqs', c.ai_faqs::text)) v(col, val)
   where c.id in (select row_id from l where tbl = 'pp_cities'))
select l.*, b.old_value, c.cur_md5,
  case when b.old_value is null then 'skip_no_backup'
       when md5(b.old_value) <> l.old_md5 then 'skip_backup_mismatch'
       when c.row_id is null then 'skip_row_missing'
       when c.cur_md5 is not distinct from l.old_md5 then 'already_restored'
       when c.cur_md5 is distinct from l.new_md5 then 'skip_edited_after_apply'
       else 'restore' end action
  from l
  left join public.seo_repair_pp_backup_20261115 b on b.tbl = l.tbl and b.row_id = l.row_id and b.col = l.col and b.old_md5 = l.old_md5
  left join cur c on c.tbl = l.tbl and c.row_id = l.row_id and c.col = l.col;

\echo '== rollback decisions'
select action, tbl, col, count(*) from seo_pp_rb group by 1, 2, 3 order by 1, 2, 3;

with u as (
  update public.pp_pools t set ai_best_for = r.old_value from seo_pp_rb r
   where r.action = 'restore' and r.tbl = 'pp_pools' and r.col = 'ai_best_for' and t.id = r.row_id and md5(t.ai_best_for) = r.new_md5
  returning t.id, r.rule_id, r.old_md5, r.new_md5)
insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, 'pp_pools', id, 'ai_best_for', new_md5, old_md5, 'restored' from u;
with u as (
  update public.pp_pools t set ai_description = r.old_value from seo_pp_rb r
   where r.action = 'restore' and r.tbl = 'pp_pools' and r.col = 'ai_description' and t.id = r.row_id and md5(t.ai_description) = r.new_md5
  returning t.id, r.rule_id, r.old_md5, r.new_md5)
insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, 'pp_pools', id, 'ai_description', new_md5, old_md5, 'restored' from u;
with u as (
  update public.pp_pools t set ai_faqs = r.old_value::jsonb from seo_pp_rb r
   where r.action = 'restore' and r.tbl = 'pp_pools' and r.col = 'ai_faqs' and t.id = r.row_id and md5(t.ai_faqs::text) = r.new_md5
  returning t.id, r.rule_id, r.old_md5, r.new_md5)
insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, 'pp_pools', id, 'ai_faqs', new_md5, old_md5, 'restored' from u;
with u as (
  update public.pp_cities t set ai_intro = r.old_value from seo_pp_rb r
   where r.action = 'restore' and r.tbl = 'pp_cities' and r.col = 'ai_intro' and t.id = r.row_id and md5(t.ai_intro) = r.new_md5
  returning t.id, r.rule_id, r.old_md5, r.new_md5)
insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, 'pp_cities', id, 'ai_intro', new_md5, old_md5, 'restored' from u;
with u as (
  update public.pp_cities t set ai_faqs = r.old_value::jsonb from seo_pp_rb r
   where r.action = 'restore' and r.tbl = 'pp_cities' and r.col = 'ai_faqs' and t.id = r.row_id and md5(t.ai_faqs::text) = r.new_md5
  returning t.id, r.rule_id, r.old_md5, r.new_md5)
insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, 'pp_cities', id, 'ai_faqs', new_md5, old_md5, 'restored' from u;

insert into public.seo_repair_pp_change_log (run_id, rule_id, tbl, row_id, col, old_md5, new_md5, action)
select current_setting('seo_pp.rb_id'), rule_id, tbl, row_id, col, new_md5, old_md5, 'rollback_' || action
  from seo_pp_rb where action <> 'restore';

do $$ declare want bigint; got bigint; bad bigint; begin
  select count(*) into want from seo_pp_rb where action = 'restore';
  select count(*) into got from public.seo_repair_pp_change_log
   where run_id = current_setting('seo_pp.rb_id') and action = 'restored' and logged_at = now();
  if want <> got then raise exception 'ABORT: % field(s) to restore but % restored', want, got; end if;
  select count(*) into bad from seo_pp_rb r
   where r.action = 'restore' and r.old_md5 is distinct from (case
     when r.tbl = 'pp_pools' and r.col = 'ai_best_for' then (select md5(ai_best_for) from public.pp_pools where id = r.row_id)
     when r.tbl = 'pp_pools' and r.col = 'ai_description' then (select md5(ai_description) from public.pp_pools where id = r.row_id)
     when r.tbl = 'pp_pools' and r.col = 'ai_faqs' then (select md5(ai_faqs::text) from public.pp_pools where id = r.row_id)
     when r.tbl = 'pp_cities' and r.col = 'ai_intro' then (select md5(ai_intro) from public.pp_cities where id = r.row_id)
     when r.tbl = 'pp_cities' and r.col = 'ai_faqs' then (select md5(ai_faqs::text) from public.pp_cities where id = r.row_id) end);
  if bad > 0 then raise exception 'ABORT: % restored field(s) do not have the old md5', bad; end if;
end $$;

